import java.util.*;
import java.io.*;

public class Main {
    static List<long[]> topKStream(long[] a, int k) {
        // Write your solution here
        // Return one array per arrival: the (up to) k most frequent values so far.
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int k = (int) in.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); a[i] = (long) in.nval;
        }
        StringBuilder sb = new StringBuilder();
        for (long[] row : topKStream(a, k)) {
            for (int i = 0; i < row.length; i++) sb.append(row[i]).append(i + 1 < row.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
